# Which e2e sections a change affects: scripts/e2e-affected.sh reads this file.
#
#   <glob>  <section>, <section>, ...
#
# A changed path takes the sections of the FIRST line whose glob matches it,
# so a specific line goes above the general one that would also match. In a
# glob, ** is any number of path elements (also none), * anything but a /, ?
# one character but a /. ALL is every section, NONE no section. @name stands
# for a group defined on a line "@name = <section>, ...", above its first use.
# A path no line matches affects every section.
#
# Changes to e2e/*.go do not come here: the script maps each changed line to
# the function it is in, and that function to the sections that reach it,
# with e2e/sections.index (generated from the code: make e2e-index).
#
# Keep it honest: a line maps a path to the sections that exercise it on the
# box, not to the ones that are named after it. When unsure, leave the path
# to the catch-all lines at the bottom (ALL). TestSectionsMap (sections_test.go)
# checks that every section named here exists and that every section is named
# by at least one line.

# ------------------------------------------------------------------ groups --

# Every section that sends requests to a hosted site through nginx.
@serving = site types, woocommerce, wordpress cache, wordpress staging, wordpress certificates, wordpress logs, wordpress slow request, wordpress safe push, wordpress releases, wordpress backups, wordpress teardown, migration import, security, woocommerce security, R-0.7 reconcile, R-5.2 reload drain, R-3.7 site lifecycle, R-5.4 routing, SR tenant data, protected paths, blocklist, site blocking, wordpress two-factor, wordpress hardening, dev mode, maintenance page, wordpress cleanup
# Every section with a PHP site (its own FPM master, pool and slice).
@php = site types, woocommerce, wordpress cache, wordpress staging, wordpress status and drift, wordpress sftp, wordpress logs, wordpress slow request, wordpress cron, wordpress safe push, wordpress releases, wordpress backups, wordpress teardown, migration import, security, woocommerce security, R-0.7 reconcile, R-5.2 reload drain, R-3.7 site lifecycle, R-5.4 routing, protected paths, wordpress two-factor, wordpress hardening, dev mode, mail relay
# Every section with a WordPress site (database, wp-cli, the connector).
@wordpress = site types, woocommerce, wordpress vulnerabilities, wordpress cache, wordpress staging, wordpress status and drift, wordpress sftp, wordpress logs, wordpress slow request, wordpress cron, wordpress safe push, wordpress releases, wordpress backups, wordpress updates, wordpress teardown, migration import, woocommerce security, woocommerce teardown, blocklist, wordpress two-factor, wordpress hardening, wordpress cleanup, mail relay
# The object cache and the loopback flush through a site's own FPM pool.
@objectcache = woocommerce, wordpress cache, wordpress sftp, wordpress backups, migration import

